class KernelStubs:
    """The host's `kernel` interface. A subclass supplies `_request`; a call the host refuses raises `KernelError`."""

    def _request(self, method: str, params: dict[str, Any]) -> Any:
        raise NotImplementedError

    def extrude(self, p: Profile, distance: float) -> Body:
        """`p` swept `distance` along its plane's normal, against it when negative."""
        r = self._request("kernel.extrude", {"p": p.to_json(), "distance": distance})
        if "err" in r:
            raise KernelError(Diagnostic.from_json(r["err"]))
        return r["ok"]

    def revolve(self, p: Profile, a: Axis, angle: float) -> Body:
        """`p` turned `angle` radians (at most a full turn) about `a`. Counted with the extrudes in the feature's sweep numbering (ADR-0011)."""
        r = self._request("kernel.revolve", {"p": p.to_json(), "a": a.to_json(), "angle": angle})
        if "err" in r:
            raise KernelError(Diagnostic.from_json(r["err"]))
        return r["ok"]

    def names(self, b: Body) -> list[PersistentRef]:
        """Every face, edge and vertex of `b`, by name."""
        r = self._request("kernel.names", {"b": b})
        if "err" in r:
            raise KernelError(Diagnostic.from_json(r["err"]))
        return [PersistentRef.from_json(x0) for x0 in r["ok"]]

    def face_frame(self, b: Body, face: PersistentRef) -> Frame:
        """The outward frame of a planar face of `b`."""
        r = self._request("kernel.face-frame", {"b": b, "face": face.to_json()})
        if "err" in r:
            raise KernelError(Diagnostic.from_json(r["err"]))
        return Frame.from_json(r["ok"])

    def measure(self, b: Body) -> MassProperties:
        """Volume, area and centroid of `b`."""
        r = self._request("kernel.measure", {"b": b})
        if "err" in r:
            raise KernelError(Diagnostic.from_json(r["err"]))
        return MassProperties.from_json(r["ok"])

    def fuse(self, target: Body, tool: Body) -> Body:
        """`target` joined with `tool`, and `target` less `tool`: new bodies, the operands left as they were."""
        r = self._request("kernel.fuse", {"target": target, "tool": tool})
        if "err" in r:
            raise KernelError(Diagnostic.from_json(r["err"]))
        return r["ok"]

    def cut(self, target: Body, tool: Body) -> Body:
        r = self._request("kernel.cut", {"target": target, "tool": tool})
        if "err" in r:
            raise KernelError(Diagnostic.from_json(r["err"]))
        return r["ok"]

    def common(self, target: Body, tool: Body) -> Body:
        """What `target` and `tool` have in common."""
        r = self._request("kernel.common", {"target": target, "tool": tool})
        if "err" in r:
            raise KernelError(Diagnostic.from_json(r["err"]))
        return r["ok"]

    def fillet(self, b: Body, edges: list[PersistentRef], radius: float) -> Body:
        """`b` with `edges` rounded at `radius` metres, or cut flat at `distance`. A feature's booleans and blends are numbered in call order (ADR-0014)."""
